import{_ as a,c as e,o as i,a5 as o}from"./chunks/framework.CxlzjCG8.js";const p=JSON.parse('{"title":"Authentication","description":"","frontmatter":{},"headers":[],"relativePath":"apps/admin/authentication.md","filePath":"apps/admin/authentication.md"}'),n={name:"apps/admin/authentication.md"};function r(s,t,c,d,u,g){return i(),e("div",{"data-pagefind-body":!0},t[0]||(t[0]=[o('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>Lightbug accounts provide access to all Lightbug interfaces and connected devices.</p><h2 id="creating-an-account" tabindex="-1">Creating an Account <a class="header-anchor" href="#creating-an-account" aria-label="Permalink to &quot;Creating an Account&quot;">​</a></h2><p>You can now create a Lightbug account directly through the admin portal.</p><p>To get started, open the admin portal, navigate to the <a href="https://admin.lightbug.cloud/#/auth/register" target="_blank" rel="noreferrer">registration page</a> and follow the account creation steps.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/7Fu00NW.png" alt="Lightbug Admin portal account creation" tabindex="0"><figcaption>Lightbug Admin portal account creation</figcaption></figure><p>There are various password requirements to ensure account security, including minimum length, character variety, and a previous breach checker.</p><p>On successful account creation, you will be directed to the login page.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/kYbF1jb.png" alt="Lightbug Admin portal account creation success" tabindex="0"><figcaption>Lightbug Admin portal account creation success</figcaption></figure><h3 id="sub-accounts" tabindex="-1">Sub Accounts <a class="header-anchor" href="#sub-accounts" aria-label="Permalink to &quot;Sub Accounts&quot;">​</a></h3><p>After creating your main account, you can add sub accounts to share device access with others from the admin portal.</p><p>For more details, see <a href="/docs/pr/16/apps/admin/devices/users#add-new-user">adding new users to devices</a>.</p><h2 id="logging-in" tabindex="-1">Logging In <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging In&quot;">​</a></h2><p>To log in to your Lightbug account, use the credentials you created during account setup.</p><p>First starting with the email address you registered with.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/xUAhQvi.png" alt="Lightbug Admin portal login" tabindex="0"><figcaption>Lightbug Admin portal login</figcaption></figure><p>Once your email is entered, available login options will be displayed, most commonly password login.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/s3yYBaN.png" alt="Lightbug Admin portal login options" tabindex="0"><figcaption>Lightbug Admin portal login options</figcaption></figure><p>Select your preferred login method, and complete the login process.</p><h3 id="password-login" tabindex="-1">Password Login <a class="header-anchor" href="#password-login" aria-label="Permalink to &quot;Password Login&quot;">​</a></h3><p>If you choose password login, enter your password and click &quot;Login&quot;.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/gUHmrhg.png" alt="Lightbug Admin portal password login" tabindex="0"><figcaption>Lightbug Admin portal password login</figcaption></figure><p>If you have forgotten your password, click the &quot;<a href="https://admin.lightbug.cloud/#/auth/request-password" target="_blank" rel="noreferrer">Forgot Password?</a>&quot; link to initiate a password reset.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>All accounts can log in to the admin panel, however you will need to be granted permissions to access different features.</p><p>Different permissions will reveal different interfaces in the side bar, as well as content throughout the admin portal.</p><table tabindex="0"><thead><tr><th>Page</th><th>user</th><th>trackerAdmin</th><th>Description</th></tr></thead><tbody><tr><td><a href="/docs/pr/16/apps/admin/devices/">Devices</a></td><td>✅</td><td>✅</td><td>List all devices on the account</td></tr><tr><td><a href="./configs.html">Configs</a></td><td></td><td>✅</td><td>Manage <code>config pages</code> that can be applied to devices</td></tr><tr><td><a href="./users.html">Users</a></td><td></td><td>✅</td><td>Manage sub users of your account</td></tr></tbody></table>',27)]))}const h=a(n,[["render",r]]);export{p as __pageData,h as default};
